<div class="toolbar"><form class="search-form" method="get"><input type="hidden" name="page" value="produits"><input type="search" name="search" value="<?= e($_GET['search'] ?? '') ?>" placeholder="Rechercher une pièce, un SKU..."><select name="category"><option value="">Toutes les catégories</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= ($_GET['category'] ?? '') == $category['id'] ? 'selected' : '' ?>><?= e($category['nom']) ?></option><?php endforeach; ?></select><button class="button button-outline" type="submit">Filtrer</button><a class="button button-ghost" href="<?= BASE_URL ?>/index.php?page=produits">Tous les produits</a></form><a class="button button-primary" href="<?= BASE_URL ?>/index.php?page=produit-form">+ Ajouter</a></div>
<div class="panel table-panel"><div class="panel-heading"><div><p class="eyebrow">CATALOGUE</p><h2>Inventaire</h2></div><span class="count-badge"><?= count($products) ?> références</span></div><div class="table-wrap"><table><thead><tr><th>Référence</th><th>Catégorie</th><th>Emplacement</th><th>Quantité</th><th>Prix vente</th><th>État</th><th></th></tr></thead><tbody><?php if (!$products): ?><tr><td colspan="7" class="empty-state">Aucune référence trouvée.</td></tr><?php endif; ?><?php foreach ($products as $product): ?><tr><td><strong><?= e($product['nom']) ?></strong><small><?= e($product['sku']) ?></small></td><td><?= e($product['categorie'] ?? 'Sans catégorie') ?></td><td><?= e($product['emplacement'] ?: '—') ?></td><td class="quantity-cell"><?= e($product['quantite']) ?></td><td><?= money($product['prix_vente']) ?></td><td><span class="status status-<?= $product['etat'] === 'Rupture' ? 'danger' : ($product['etat'] === 'Stock faible' ? 'warning' : 'ok') ?>"><?= e($product['etat']) ?></span></td><td class="actions"><a class="icon-button" title="Modifier" href="<?= BASE_URL ?>/index.php?page=produit-form&id=<?= e($product['id']) ?>">✎</a><form method="post" action="<?= BASE_URL ?>/index.php?page=produit-delete" data-confirm="Supprimer cette référence ? Les mouvements historiques seront conservés."><input type="hidden" name="id" value="<?= e($product['id']) ?>"><button class="icon-button danger-text" title="Supprimer">×</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
